import csv
import io
from collections import defaultdict


def _parse_csv_rows(csv_text: str):
    """Return a csv.DictReader for the given text, or None on failure."""
    try:
        reader = csv.DictReader(io.StringIO(csv_text))
    except Exception:
        return None

    if reader.fieldnames is None:
        try:
            next(iter(reader), None)
        except Exception:
            return None
        if reader.fieldnames is None:
            return None

    return reader


def _extract_valid_row(row: dict):
    """
    Validate a single CSV row.
    Return (region, product, quantity, cents) on success, or None if malformed.
    """
    required_fields = {"region", "product", "quantity", "cents"}
    if not required_fields.issubset(row.keys()):
        return None

    region = row.get("region")
    product = row.get("product")
    quantity_str = row.get("quantity")
    cents_str = row.get("cents")

    if region is None or product is None or quantity_str is None or cents_str is None:
        return None

    region = region.strip()
    product = product.strip()
    quantity_str = quantity_str.strip()
    cents_str = cents_str.strip()

    if not region or not product:
        return None

    try:
        quantity = int(quantity_str)
        cents = int(cents_str)
    except (ValueError, TypeError):
        return None

    return region, product, quantity, cents


def _aggregate_rows(reader) -> defaultdict:
    """Iterate over DictReader rows and accumulate totals by (region, product)."""
    aggregated = defaultdict(lambda: {"quantity": 0, "cents": 0})
    for row in reader:
        parsed = _extract_valid_row(row)
        if parsed is None:
            continue
        region, product, quantity, cents = parsed
        key = (region, product)
        aggregated[key]["quantity"] += quantity
        aggregated[key]["cents"] += cents
    return aggregated


def _build_result(aggregated: defaultdict, min_quantity: int) -> list:
    """Convert aggregated data to sorted list of dicts, filtered by min_quantity."""
    result = [
        {
            "region": region,
            "product": product,
            "quantity": data["quantity"],
            "cents": data["cents"],
        }
        for (region, product), data in aggregated.items()
        if data["quantity"] >= min_quantity
    ]
    result.sort(key=lambda x: (x["region"], x["product"]))
    return result


def aggregate_sales(csv_text: str, *, min_quantity: int = 0) -> list[dict]:
    """
    Parse CSV text with headers region, product, quantity, cents.
    Skip malformed rows, missing fields, and rows with non-integer quantity or cents.
    Group by (region, product), summing quantity and cents.
    Return rows sorted by region then product.
    Omit groups whose final aggregate quantity is less than min_quantity.
    """
    reader = _parse_csv_rows(csv_text)
    if reader is None:
        return []

    aggregated = _aggregate_rows(reader)
    return _build_result(aggregated, min_quantity)

